import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
const read = file => readFile(path.join(root, file), 'utf8');
const stripModuleSyntax = source => source
  .replace(/^\s*import\s+[\s\S]*?from\s+['"][^'"]+['"];?\s*$/gm, '')
  .replace(/^\s*export\s*\{[\s\S]*?\};?\s*$/gm, '')
  .replace(/\bexport\s+(?=(?:async\s+)?(?:const|function|class)\b)/g, '');

const manifest = JSON.parse(await read('assets/runtime/sprites.json'));
const modules = await Promise.all([
  read('game/config.js'),
  read('game/load-manifest.js'),
  read('game/routes.js'),
  read('game/collision.js'),
  read('game/simulation.js'),
  read('game/depth.js'),
  read('game/renderer.js'),
  read('game/save.js'),
  read('game/input.js'),
  read('game/audio.js'),
  read('game/app.js'),
]);
const output = `/* Generated by tools/build-app-bundle.mjs for direct file:// use. */
(async()=>{
globalThis.__SNEAKERS_RUNTIME_MANIFEST__=${JSON.stringify(manifest)};
${modules.map(stripModuleSyntax).join('\n')}
})();
`;
await writeFile(path.join(root, 'game/app.bundle.js'), output);
console.log('Game fallback bundle rebuilt.');
